import{_ as a,o,c as t,a2 as i}from"./chunks/framework.mzJ8I8R4.js";const m=JSON.parse('{"title":"下载和安装","description":"","frontmatter":{},"headers":[],"relativePath":"guide/install.md","filePath":"guide/install.md"}'),l={name:"guide/install.md"};function r(d,e,n,s,p,h){return o(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="下载和安装" tabindex="-1">下载和安装 <a class="header-anchor" href="#下载和安装" aria-label="Permalink to &quot;下载和安装&quot;">​</a></h1><p>NextTodo 有 Android、macOS 和 Windows App。连接自己的服务器时，也可以在浏览器里使用网页版。下面的下载链接总是最新版。</p><h2 id="android" tabindex="-1">Android <a class="header-anchor" href="#android" aria-label="Permalink to &quot;Android&quot;">​</a></h2><p>要求 Android 8.0 及以上。</p><ol><li>用手机浏览器打开 <a href="https://github.com/JunieXD/NextTodo/releases/latest/download/NextTodo-android.apk" target="_blank" rel="noreferrer">NextTodo-android.apk</a>，下载安装包。</li><li>下载完成后点开它。第一次安装从浏览器下载的应用时，系统会提示不允许安装未知来源的应用：点击“设置”，打开“允许来自此来源的应用”，返回后继续安装。各品牌手机的叫法略有不同。</li><li>打开 NextTodo，<a href="./#modes">选择用法</a>。</li></ol><p>要按时收到截止提醒，打开 App 的“设置 → 提醒和后台”，按提示允许“通知”和“准时提醒”。小米、红米等使用澎湃 OS 的手机，还要点“自启动和省电”一行的“打开设置”，允许自启动，并把省电策略设为“无限制”。</p><p>桌面小组件：长按手机桌面的空白处，选择“小组件”，找到 NextTodo，拖到桌面上。小组件显示“接下来”，可以直接勾选完成或添加事项。</p><h2 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h2><p>要求 Apple 芯片（M1 及以后），macOS 14 及以上。</p><ol><li><p>下载 <a href="https://github.com/JunieXD/NextTodo/releases/latest/download/NextTodo-macos-arm64.dmg" target="_blank" rel="noreferrer">NextTodo-macos-arm64.dmg</a>，双击打开。</p></li><li><p>把窗口里的 NextTodo 拖进“应用程序”文件夹。不要直接在这个窗口里打开它，否则以后无法安装命令行。</p></li><li><p>打开“应用程序”文件夹，双击 NextTodo。第一次打开时，系统会提示无法验证开发者：</p><ol><li>点击“完成”关掉提示。</li><li>打开“系统设置 → 隐私与安全性”，在页面下方找到关于 NextTodo 的提示，点击“仍要打开”，按提示输入登录密码。</li><li>之后可以正常打开，不会再提示。</li></ol><p>出现提示是因为 NextTodo 没有向苹果付费做签名公证，不代表它有问题。</p></li><li><p><a href="./#modes">选择用法</a>。</p></li></ol><p>关掉窗口后，NextTodo 仍在菜单栏里，继续同步和提醒。点菜单栏的图标打开快速添加，右键图标选“退出”才会退出。在任何应用里按 ⌃⌥空格（Control + Option + 空格）也能快速添加。要开机时自动运行，在设置里打开“开机自启”。</p><h2 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h2><p>要求 Windows 10 或 11，x64。</p><ol><li>下载 <a href="https://github.com/JunieXD/NextTodo/releases/latest/download/NextTodo-windows-x64-setup.exe" target="_blank" rel="noreferrer">NextTodo-windows-x64-setup.exe</a>，双击运行。</li><li>出现“Windows 已保护你的电脑”时，点击“更多信息”，再点击“仍要运行”。原因和 macOS 一样，安装程序没有付费签名。</li><li>按提示完成安装。安装程序只装给当前用户，不需要管理员权限；系统缺少 WebView2 时会自动下载。</li><li><a href="./#modes">选择用法</a>。</li></ol><p>关掉窗口后，NextTodo 仍在任务栏右下角的托盘里，继续同步和提醒。右键托盘图标选“退出”才会退出。在任何应用里按 Ctrl + Alt + 空格也能快速添加。要开机时自动运行，在设置里打开“开机自启”。</p><h2 id="网页版" tabindex="-1">网页版 <a class="header-anchor" href="#网页版" aria-label="Permalink to &quot;网页版&quot;">​</a></h2><p>只在连接服务器时可用：用浏览器打开服务器的域名，登录即可。</p><p>网页版可以安装成独立的窗口：Chrome 和 Edge 点地址栏右侧的“安装”图标；iPhone 和 iPad 的 Safari 点“分享 → 添加到主屏幕”。网页版不弹出截止提醒，需要提醒的请用 App。</p><h2 id="更新" tabindex="-1">更新 <a class="header-anchor" href="#更新" aria-label="Permalink to &quot;更新&quot;">​</a></h2><p>不用手动更新：</p><ul><li><strong>连接服务器时</strong>：App 从服务器获取更新，服务器升级后随之更新。Android 下次打开时生效，需要换安装包时会提示；电脑上在后台下载，提示“重启”后生效。</li><li><strong>在本机使用时</strong>：App 从 GitHub 获取更新，有新版本时同样会提示。</li></ul><p>版本号在“设置 → 关于”里查看。</p>',22)])])}const x=a(l,[["render",r]]);export{m as __pageData,x as default};
